import{_ as l,a0 as o,w as r,s as u,ao as e,I as n,x as p,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux 版 WhatsApp | LCTT x X-CMD","titleTemplate":false,"description":"Linux 版 WhatsApp | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 版 WhatsApp | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 版 WhatsApp | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230615.1 ⭐️ WhatsApp for Linux A Flatpak Desktop App for Distributions","title":"Linux 版 WhatsApp","tag":"202306","desc":""},"relativePath":"202306/20230615.1 ⭐️ WhatsApp for Linux A Flatpak Desktop App for Distributions.md","filePath":"[post].md"}'),d={name:"202306/20230615.1 ⭐️ WhatsApp for Linux A Flatpak Desktop App for Distributions.md"};function h(x,t,f,m,b,g){const a=o("Link");return r(),u("div",null,[t[21]||(t[21]=e('<h1 id="linux-版-whatsapp" tabindex="-1">Linux 版 WhatsApp <a class="header-anchor" href="#linux-版-whatsapp" aria-label="Permalink to “Linux 版 WhatsApp”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/29/152308bjkgagd8guq1qggj.jpg" alt=""></p><blockquote><p>一款出色的 Flatpak 應用，可從 Linux 桌面訪問 WhatsApp。</p></blockquote><p>WhatsApp 是流行的手機通訊平台，在許多國家都很受歡迎。用户通常通過 Play 商店或 App Store 中的移動應用訪問它。然而，WhatsApp 從未推出任何適用於 Linux 的官方桌面客户端。</p><p>儘管你可以使用瀏覽器訪問 WhatsApp，這是從任何桌面（包括 Linux）訪問消息的官方方式。</p><p>一個新的非官方 WhatsApp Flatpak 桌面應用出現了，你可以無縫地使用它進行通信。</p><p>那麼，這個 GTK 應用有哪些功能？</p><h3 id="linux-版-whatsapp-的功能" tabindex="-1">“Linux 版 WhatsApp” 的功能 <a class="header-anchor" href="#linux-版-whatsapp-的功能" aria-label="Permalink to ““Linux 版 WhatsApp” 的功能”">​</a></h3><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/WhatsApp-for-Linux-image-credit-developer.jpg" alt="Linux 版 WhatsApp（圖片來源開發者）"></p><p>藉助這款新的桌面應用，Linux 桌面用户可以在他們最喜歡的桌面環境中享受 WhatsApp 的所有熟悉功能。現在，你可以在 Linux 發行版上輕鬆訪問所有功能，例如發送消息、共享媒體文件以及進行語音和視頻通話。</p><p>“Linux 版 WhatsApp” 應用還提供鍵盤快捷鍵，確保應用內的無縫導航和交互。使用此應用，你可以放大和縮小以仔細查看圖像和文本，或切換到全屏模式以獲得無干擾的聊天體驗。該應用還包括一個系統托盤圖標，即使在應用最小化時也可以快速訪問和通知。</p><p>此外，你可以自定義應用以滿足你的喜好。通過按 <code>Alt+H</code>，你可以輕鬆顯示或隱藏標題欄，從而更好地控制工作區。該應用還支持系統語言的本地化，確保你可以輕鬆地與世界各地的朋友和家人進行交流。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/Settings.jpg" alt="設置"></p><p>Linux 版 WhatsApp 應用的一項值得注意的功能是支持系統語言的拼寫檢查。要啓用此功能，你必須安裝相應的詞典，例如美國英語的 hunspell-en_us 包。</p><h3 id="技術細節" tabindex="-1">技術細節 <a class="header-anchor" href="#技術細節" aria-label="Permalink to “技術細節”">​</a></h3><p>如果你想知道，它不是一個 Electron 應用。它是使用原生 C++ 編寫的，確保了最佳的性能和安全性。它依賴於各種免費和開源庫，例如 intltool、gtkmm-3.0、webkit2gtk-4.0、ayatana-appindicator3-0.1、libcanberra 以及用於拼寫檢查的 libhunspell（可選）。</p>',16)),n("p",null,[t[1]||(t[1]=p("你可以從 ",-1)),i(a,{href:"https://github.com/eneshecan/whatsapp-for-linux"},{default:s(()=>[...t[0]||(t[0]=[p("GitHub 上的源碼",-1)])]),_:1}),t[2]||(t[2]=p("瞭解有關此應用的更多信息。",-1))]),t[22]||(t[22]=n("h3",{id:"安裝",tabindex:"-1"},[p("安裝 "),n("a",{class:"header-anchor",href:"#安裝","aria-label":"Permalink to “安裝”"},"​")],-1)),n("p",null,[t[4]||(t[4]=p("首先，你必須為你的 Linux 發行版設置 Flatpak 和 Flathub。使用 ",-1)),i(a,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:s(()=>[...t[3]||(t[3]=[p("本指南",-1)])]),_:1}),t[5]||(t[5]=p(" 來設置。",-1))]),t[23]||(t[23]=e('<p>安裝後，運行以下命令進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install com.github.eneshecan.WhatsAppForLinux</span></span></code></pre></div><p>你可以在應用列表中找到該應用。</p><h3 id="運行應用" tabindex="-1">運行應用 <a class="header-anchor" href="#運行應用" aria-label="Permalink to “運行應用”">​</a></h3><p>打開應用後，設置與 WhatsApp 網頁類似。打開手機的 WhatsApp 應用並掃描應用中的二維碼。這樣就完成了。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/WhatsApp-for-Linux.jpg" alt="Linux 版 WhatsApp"></p><p>請注意，這是一個非官方的應用。因此，請謹慎使用。你還可以查看 GitHub 以獲取有關此應用的更多詳細信息。</p><p><em>（題圖：MJ/de9d18fe-fb3f-4d88-8723-761ebbee5f38）</em></p><hr>',9)),n("p",null,[t[7]||(t[7]=p("via: ",-1)),i(a,{href:"https://www.debugpoint.com/whatsapp-for-linux/"},{default:s(()=>[...t[6]||(t[6]=[p("https://www.debugpoint.com/whatsapp-for-linux/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=p("作者：",-1)),i(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:s(()=>[...t[8]||(t[8]=[p("Arindam",-1)])]),_:1}),t[13]||(t[13]=p(" 選題：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:s(()=>[...t[9]||(t[9]=[p("lkxed",-1)])]),_:1}),t[14]||(t[14]=p(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:s(()=>[...t[10]||(t[10]=[p("geekpi",-1)])]),_:1}),t[15]||(t[15]=p(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[11]||(t[11]=[p("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=p("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[16]||(t[16]=[p("LCTT",-1)])]),_:1}),t[19]||(t[19]=p(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:s(()=>[...t[17]||(t[17]=[p("Linux中國",-1)])]),_:1}),t[20]||(t[20]=p(" 榮譽推出",-1))])])}const L=l(d,[["render",h]]);export{w as __pageData,L as default};
